namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var step = i + 1;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;
        var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

        <button class="@cssClass"
                disabled="@(!isCompleted)"
                @onclick="() => OnStepClicked.InvokeAsync(step)"
                aria-current="@(isCurrent ? "step" : null)">
            <span class="step-number">
                @if (isCompleted)
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @step
                }
            </span>
            <span class="step-name">@StepNames[i]</span>
        </button>

        @if (i < StepNames.Length - 1)
        {
            <span class="step-connector @(isCompleted ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    private static readonly string[] StepNames =
    [
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    ];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<fieldset class="work-entry">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)e.Value!)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void Update(WorkEntryModel updated) => OnChanged.InvokeAsync(updated);

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        OnChanged.InvokeAsync(updated);
    }
}

@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<fieldset class="reference-entry">
    <legend>Reference @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button type="button" class="btn-remove" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Entry.Name"
               @onchange="e => Update(Entry with { Name = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Entry.Relationship"
               @onchange="e => Update(Entry with { Relationship = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email"
                   @onchange="e => Update(Entry with { Email = (string?)e.Value ?? "" })" />
        </div>

        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Entry.Phone"
                   @onchange="e => Update(Entry with { Phone = (string?)e.Value ?? "" })" />
        </div>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<ReferenceModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void Update(ReferenceModel updated) => OnChanged.InvokeAsync(updated);
}

@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<section class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(Error))
    {
        <div class="validation-error" role="alert">@Error</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@Model.FullName"
               @onchange="e => Model = Model with { FullName = (string?)e.Value ?? "" }" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Model.Email"
               @onchange="e => Model = Model with { Email = (string?)e.Value ?? "" }" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Model.Phone"
               @onchange="e => Model = Model with { Phone = (string?)e.Value ?? "" }" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Model.Address"
                  @onchange="e => Model = Model with { Address = (string?)e.Value ?? "" }"></textarea>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn-primary" disabled="@IsValidating" @onclick="HandleNext">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback<PersonalInfoModel> OnNext { get; set; }
    [Parameter] public EventCallback<PersonalInfoModel> ModelChanged { get; set; }

    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private string? Error;
    private bool IsValidating;

    private async Task HandleNext()
    {
        Error = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            Error = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!emailValid)
            {
                Error = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(Model);
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<section class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(Error))
    {
        <div class="validation-error" role="alert">@Error</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index"
                       ShowRemove="Entries.Count > 1"
                       OnChanged="entry => UpdateEntry(index, entry)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter] public EventCallback<List<WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? Error;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void UpdateEntry(int index, WorkEntryModel entry)
    {
        Entries[index] = entry;
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
    }

    private void HandleBack() => OnBack.InvokeAsync();

    private void HandleNext()
    {
        Error = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                Error = "Company name and job title are required for each position.";
                return;
            }
        }

        OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<section class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(Error))
    {
        <div class="validation-error" role="alert">@Error</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="References[index]"
                       Index="index"
                       ShowRemove="References.Count > 2"
                       OnChanged="entry => UpdateReference(index, entry)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? Error;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void UpdateReference(int index, ReferenceModel entry)
    {
        References[index] = entry;
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void HandleBack() => OnBack.InvokeAsync();

    private void HandleNext()
    {
        Error = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) ||
                string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email))
            {
                Error = "Name, relationship, and email are required for each reference.";
                return;
            }
        }

        OnNext.InvokeAsync(References);
    }
}

@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<section class="step-content">
    <h2>Cover Letter</h2>

    @if (!string.IsNullOrEmpty(Error))
    {
        <div class="validation-error" role="alert">@Error</div>
    }

    <div class="form-group">
        <label>Write your cover letter</label>
        <textarea rows="12" maxlength="@MaxLength" value="@CoverLetter"
                  @oninput="e => CoverLetter = (string?)e.Value ?? """></textarea>
        <span class="char-count">@CoverLetter.Length / @MaxLength characters</span>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</section>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? Error;

    private void HandleBack() => OnBack.InvokeAsync();

    private void HandleNext()
    {
        Error = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            Error = "Please write a cover letter.";
            return;
        }

        OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<section class="step-content">
    <h2>Review & Submit</h2>

    @if (!string.IsNullOrEmpty(Error))
    {
        <div class="validation-error" role="alert">@Error</div>
    }

    @if (IsSubmitted)
    {
        <div class="submission-confirmation" role="status">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <p><strong>@entry.Title</strong> at @entry.Company</p>
                    <p>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</p>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <p><strong>@r.Name</strong> (@r.Relationship)</p>
                    <p>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</p>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(4)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
            <button type="button" class="btn-primary btn-submit" disabled="@IsSubmitting" @onclick="HandleSubmit">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public string? Error { get; set; }

    private void HandleBack() => OnBack.InvokeAsync();
    private void HandleSubmit() => OnSubmit.InvokeAsync();
}

