{"path": "/tmp/sv-b5725ebcbfc942bc9dbef6bcb2bd080f/Components/Pages/Apply/ReviewStep.razor", "file_text": "@namespace sv_b5725ebcbfc942bc9dbef6bcb2bd080f.Components.Pages.Apply

<section class="step-content">
    <h2>Review & Submit</h2>

    @if (!string.IsNullOrEmpty(Error))
    {
        <div class="validation-error" role="alert">@Error</div>
    }

    @if (IsSubmitted)
    {
        <div class="submission-confirmation" role="status">
            <h3>&#10003; Application Submitted!</h3>
            <p>Your application has been received. Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <p><strong>@entry.Title</strong> at @entry.Company</p>
                    <p>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</p>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <p><strong>@r.Name</strong> (@r.Relationship)</p>
                    <p>@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")</p>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-link" @onclick="() => OnEdit.InvokeAsync(4)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="HandleBack">Back</button>
            <button type="button" class="btn-primary btn-submit" disabled="@IsSubmitting" @onclick="HandleSubmit">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</section>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int ApplicationId { get; set; }
    [Parameter] public string? Error { get; set; }

    private void HandleBack() => OnBack.InvokeAsync();
    private void HandleSubmit() => OnSubmit.InvokeAsync();
}
"}

